 *
 * 示例：
 *   当前页面栈: [Page1, Page2, Page3, Page4, Page5]
 *   调用: lv_pm_close_to_page_msg(LV_PM_ID_MAIN, NULL)
 *   结果: [Page1, Page1正在打开动画中]
 *   Page5, Page4, Page3, Page2 分别播放关闭动画后删除
 *
 * ✓ 每个页面都有完整的生命周期回调
 * ✓ 所有关闭页面都有关闭动画
 * ✓ 目标页面有打开动画
 * ✓ 资源释放安全
 */
int lv_pm_close_to_page_msg(lv_pm_id target_id, void* msg_data)
{
    _nav_preempt_if_busy();

    if (g_pm_history_count <= 1) {
        LV_LOG_ERROR("[PAGE_MANAGER] 无法返回（路由表大小 <= 1）");
        return -1;
    }

    /* 查找目标页面在历史栈中的位置 */
    int target_index = -1;
    for (int i = 0; i < g_pm_history_count; i++) {
        if (g_pm_history[i] == target_id) {
            target_index = i;
            break;
        }
    }

    if (target_index < 0) {
        LV_LOG_ERROR("[PAGE_MANAGER] [CLOSE_TO] 目标页面不在路由表中: ID=%d",
                     target_id);
        return -3;
    }

    if (target_index == g_pm_history_count - 1) {
        LV_LOG_ERROR("[PAGE_MANAGER] [CLOSE_TO] 当前页面就是目标页面");
        return -1;
    }

    /* ================== 关闭所有中间页面 ================== */
    int pages_to_close = g_pm_history_count - target_index - 1;
    LV_LOG_INFO("[PAGE_MANAGER] [CLOSE_TO] 需要关闭 %d 个中间页面", pages_to_close);

    for (int i = g_pm_history_count - 1; i > target_index; i--) {
        lv_pm_id cur_id = g_pm_history[i];
        lv_pm_page_t page = _get_page_by_id(cur_id);

        if (page == NULL) {
            LV_LOG_ERROR("[PAGE_MANAGER] [CLOSE_TO] 页面无效: ID=%d", cur_id);
            g_pm_history_count--;
            continue;
        }

        page->flag.is_back = 1;

        LV_LOG_INFO("[PAGE_MANAGER] [CLOSE_TO] 关闭页面: ID=%d, Name=%s",
               page->id, page->name);

        /* Step 1: will_disappear - 在隐藏前通知 */
        if (page->will_disappear_cb) {
            page->will_disappear_cb(page);
        }

        /* Step 2: 启动关闭动画 */
        lv_pm_anima_play(page, LV_PM_ANIMA_EXIT, NULL, _on_batch_close_animation_complete);
    }

    /* ================== 更新路由栈 ================== */
    g_pm_history_count = target_index + 1;

    /* ================== 显示目标页面 ================== */
    lv_pm_page_t target_page = _get_page_by_id(target_id);
    if (target_page == NULL) {
        LV_LOG_ERROR("[PAGE_MANAGER] [CLOSE_TO] 目标页面无效: ID=%d",
                     target_id);
        return -2;
    }

    target_page->flag.is_back = 1;

    LV_LOG_INFO("[PAGE_MANAGER] [CLOSE_TO] 显示目标页面: ID=%d, Name=%s",
           target_page->id, target_page->name);

    _set_input_group(target_page->group);

    _pm_msg_replace(target_page, msg_data);

    /* will_appear */
    if (target_page->will_appear_cb) {
        target_page->will_appear_cb(target_page);
    }

    /* 恢复定时器 */
    if (target_page->page_timer != NULL) {
        lv_timer_resume(target_page->page_timer);
    }

    /* 显示页面 */
    if (target_page->page != NULL) {
        lv_obj_clear_flag(target_page->page, LV_OBJ_FLAG_HIDDEN);
    }

    lv_pm_anima_play(target_page, LV_PM_ANIMA_ENTER, NULL, _on_back_open_animation_complete);

    LV_LOG_INFO("[PAGE_MANAGER] [CLOSE_TO] 已返回目标页面: ID=%d, Name=%s",
           target_page->id, target_page->name);

    return 0;
}


/**
 * @brief lv_pm jump to page msg。
 */
int lv_pm_jump_to_page_msg(lv_pm_id target_id, void * msg_data)
{
    _nav_preempt_if_busy();
    return lv_pm_close_to_page_msg(target_id, msg_data);
}

/**
 * @brief 无动画快速返回到指定页面（最快，但需要谨慎）
 *
 * 这是一个新增的 API，用于确实不需要动画的场景
 *
 * 特点：
 *   - 没有关闭和打开动画
 *   - 但完全保证生命周期回调的安全执行顺序
 *   - 比 lv_pm_close_to_page_msg() 快，但没有动画效果
 *
 * 使用场景：
 *   - 用户按下硬件返回键，需要最快的响应
 *   - 某些页面禁用动画
 *   - 需要立即跳转到特定页面
 *
 * 注意：这个函数直接调用回调，但顺序是安全的
 */
int lv_pm_jump_to_page_msg_no_animation(lv_pm_id target_id, void* msg_data)
{
    _nav_preempt_if_busy();

    if (g_pm_history_count <= 1) {
        LV_LOG_ERROR("[PAGE_MANAGER] 无法返回（路由表大小 <= 1）");
        return -1;
    }

    /* 查找目标页面在历史栈中的位置 */
    int target_index = -1;
    for (int i = 0; i < g_pm_history_count; i++) {
        if (g_pm_history[i] == target_id) {
            target_index = i;
            break;
        }
    }

    if (target_index < 0) {
        LV_LOG_ERROR("[PAGE_MANAGER] [JUMP_NO_ANIMA] 目标页面不在路由表中: ID=%d",
                     target_id);
        return -3;
    }

    if (target_index == g_pm_history_count - 1) {
        LV_LOG_ERROR("[PAGE_MANAGER] [JUMP_NO_ANIMA] 当前页面就是目标页面");
        return -1;
    }

    /* ================== 关闭所有中间页面（无动画） ================== */
    int pages_to_close = g_pm_history_count - target_index - 1;
    LV_LOG_INFO("[PAGE_MANAGER] [JUMP_NO_ANIMA] 需要关闭 %d 个中间页面（无动画）",
           pages_to_close);

    for (int i = g_pm_history_count - 1; i > target_index; i--) {
        lv_pm_id cur_id = g_pm_history[i];
        lv_pm_page_t page = _get_page_by_id(cur_id);

        if (page == NULL) {
            LV_LOG_ERROR("[PAGE_MANAGER] [JUMP_NO_ANIMA] 页面无效: ID=%d",
                         cur_id);
            continue;
        }

        LV_LOG_INFO("[PAGE_MANAGER] [JUMP_NO_ANIMA] 关闭页面: ID=%d, Name=%s",
               page->id, page->name);

        /* 使用安全的无动画关闭函数 */
        _close_page_without_animation(page);

        /* 删除页面对象 */
        lv_pm_delete_page(page->id);

    }

    for (uint32_t i = 0; i < 3u; i++) {
        helm_anim_stop(objs[i], helm_sb_in_exec);
        helm_sb_in_settle(objs[i]);
    }
    s_sb_in_visible = true;
}

/** @brief 起一组：先清同对象旧动画并同步落起始态，再走一条带 delay 的 lv_anim。 */
static void helm_sb_in_run(lv_obj_t * obj, uint32_t delay)
{
    lv_anim_t a;

    if (obj == NULL) {
        return;
    }

    /* 等同 helm_anim_run 的约定：同 var + exec 的旧动画先删。 */
    helm_anim_stop(obj, helm_sb_in_exec);
    /* 起始态同步落位：上一轮若被打断（快速退出/换主题重建），
     * 避免先闪一帧旧位置/旧透明度再从头走。 */
    helm_sb_in_exec(obj, 0);

    lv_anim_init(&a);
    lv_anim_set_var(&a, obj);
    lv_anim_set_values(&a, 0, 255);
    lv_anim_set_duration(&a, HELM_SB_IN_MS);
    lv_anim_set_delay(&a, delay);
    lv_anim_set_path_cb(&a, lv_anim_path_ease_out);
    lv_anim_set_exec_cb(&a, helm_sb_in_exec);
    lv_anim_set_completed_cb(&a, helm_sb_in_done);
    if (lv_anim_start(&a) == NULL) {
        /* 动画对象分配失败（内存紧张）⇒ 没有 completed 回调，必须立刻落末态，
         * 否则这一组会永久停在 opa=0（周期刷新不会重跑入场）。 */
        helm_sb_in_settle(obj);
    }
}

/**
 * @brief 主界面入场动效（幂等，可重复调用）。
 *
 * @details 触发点两处：① `map_will_appear()`（开机 splash 关闭后进主界面、
 *          从菜单/USB/工厂页回到主界面）；② `helm_shell_rebuild_once()` 末尾
 *          （换主题把控件换新后重播）。两处互斥，见文件里的 `s_theme_rebuild_pending` 说明。
 * @note 卡片此刻不可见（骑行页）或屏幕挂起：不播，但必须落到末态 ——
 *       下次显示时不能是一块透明的卡片。
 */
void helm_shell_enter_anim(void)
{
    static const uint32_t delays[3] = {
        /* 顺序与 objs[] 对齐：0=时钟块、1=状态列、2=操作条。 */
        HELM_SB_IN_DLY,                              /* clock 40~240 */
        HELM_SB_IN_DLY + HELM_SB_IN_GAP,             /* stat 120~320 */
        HELM_SB_IN_DLY                               /* cta   40~240（与时钟同波） */
    };
    lv_obj_t * objs[3];
    uint32_t i;

    if (!s_sh.attached) {
        return;
    }

    objs[0] = s_sh.sb_clock;
    objs[1] = s_sh.sb_stat;
    objs[2] = s_sh.sb_cta;

    /*
     * 有待办主题重建：重建会把这三个对象整批换新（`helm_shell_rebuild_once` 末尾
     * 还会再调一次本函数，那一轮才真正播）。这一轮**不能**落末态：页面 220 ms
     * 淡入会把旧控件先亮出来，随后重建换新、新控件再从 0 淡入 ⇒ 内容"出现→消失→
     * 再出现"。所以这里保持它们停在**起始透明态**（opa=0、下移），让页面淡入时
     * 这块本来就没内容。
     *
     * 兜底：万一重建没来（不在主界面/转场一直没结束），一次性定时器在 500 ms 后
     * 落末态，绝不把时钟/状态列/操作条永久留在透明。
     */
    if (s_theme_rebuild_pending) {
        s_sb_in_visible = false;
        for (i = 0; i < 3u; i++) {
            helm_anim_stop(objs[i], helm_sb_in_exec);
            helm_sb_in_exec(objs[i], 0);
        }

        if (s_sb_in_wait == NULL) {
            s_sb_in_wait = lv_timer_create(helm_sb_in_wait_cb, 500, NULL);
            if (s_sb_in_wait != NULL) {
                lv_timer_set_repeat_count(s_sb_in_wait, 1);
            } else {
                /* 定时器都建不出来（内存紧张）：没有兜底就必须当场落末态，
                 * 否则重建万一不来，这三块会永久透明。 */
                for (i = 0; i < 3u; i++) {
                    helm_sb_in_settle(objs[i]);
                }
                s_sb_in_visible = true;
            }
        }
        return;
    }

    /* 有兜底在等 ⇒ 这一轮是重建后的真正入场，撤掉它（否则它会在 500 ms 处
     * 把动画中途落末态）。 */
    if (s_sb_in_wait != NULL) {
        lv_timer_delete(s_sb_in_wait);
        s_sb_in_wait = NULL;
    }

    if (!helm_obj_shown(s_sh.sb_card) || helm_anim_is_suspended()) {
        for (i = 0; i < 3u; i++) {
            helm_anim_stop(objs[i], helm_sb_in_exec);
            helm_sb_in_settle(objs[i]);
        }
        return;
    }

    s_sb_in_visible = true;
    for (i = 0; i < 3u; i++) {
        helm_sb_in_run(objs[i], delays[i]);
    }
}

