/**
 * @file ui_cta_probe.c
 * @brief TEMP PROBE（WP-CTA/R1）：菜单往返 → 主界面 CTA 入场时序量化。
 *
 * 只在环境变量 SIM_CTA_PROBE_DIR 给了目录时启用，其余情况什么都不做。
 * 流程：等开机完成 → 打开菜单 → 等 60 拍 → 关闭菜单（记 t0）→
 *       之后每拍（10 ms 虚拟时间）记录 LVGL 的 flush 次数/面积；
 *       给了 SIM_CTA_PROBE_SHOTS=1 时再每拍存一张截图 ret_NNN.png。
 *
 * 这只是模拟器的取证工具，不属于产品代码。
 */

#include <errno.h>
#include <stdarg.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>

#include "sim.h"
#include "sim_config.h"

#include "bicycle_page_ids.h"
#include "lvgl_page.h"
#include "lv_pm_core.h"
#include "live_map/map_page.h"

#define PROBE_TICK_MS   10u
#define PROBE_AFTER     45   /* 关菜单后采样拍数：45×10 ms = 450 ms */
#define PROBE_BOOT_MAX  2000

static struct {
    bool enabled;
    bool shots;
    bool started;
    bool done;
    char dir[480];
    int phase;
    int waited;
    int boot_wait;
    int nav_wait;
    int n;
    uint32_t t0;
    lv_timer_t *tmr;
} s;

static void probe_log(const char *fmt, ...)
{
    va_list ap;

    fputs("[cta] ", stdout);
    va_start(ap, fmt);
    vprintf(fmt, ap);
    va_end(ap);
    fputc('\n', stdout);
    fflush(stdout);
}

static bool probe_mkdir_p(const char *dir)
{
    char tmp[sizeof(s.dir)];
    size_t len = strlen(dir);

    if (len == 0 || len >= sizeof(tmp)) {
        return false;
    }
    memcpy(tmp, dir, len + 1);
    for (char *p = tmp + 1; *p; p++) {
        if (*p != '/') {
            continue;
        }
        *p = '\0';
        if (mkdir(tmp, 0777) != 0 && errno != EEXIST) {
            return false;
        }
        *p = '/';
    }
    if (mkdir(tmp, 0777) != 0 && errno != EEXIST) {
        return false;
    }
    return true;
}

static void probe_shot(int idx)
{
    char path[sizeof(s.dir) + 64];
    const uint16_t *fb;
    int w = 0;
    int h = 0;

    lv_obj_invalidate(lv_screen_active());
    lv_refr_now(NULL);
    fb = sim_display_shadow(&w, &h);
    if (snprintf(path, sizeof(path), "%s/ret_%03d.png", s.dir, idx) >= (int)sizeof(path)) {
        return;
    }
    if (!sim_png_write(path, fb, w, h)) {
        fprintf(stderr, "[cta] shot FAILED %s\n", path);
    }
}

static bool probe_boot_ready(void)
{
    bicycle_pm_id_t id = lvgl_page_current_id();

    if (lv_pm_nav_busy()) {
        return false;
    }
    if (id == BICYCLE_PM_ID_STARTUP) {
        return false;
    }
    return lvgl_page_map() != NULL;
}

static void probe_finish(void)
{
    s.done = true;
    if (s.tmr) {
        lv_timer_delete(s.tmr);
        s.tmr = NULL;
    }
    probe_log("done (%d samples)", s.n);
}

static void probe_tick_cb(lv_timer_t *tmr)
{
    uint32_t fn = 0, fpx = 0, fmax = 0;

    (void)tmr;
    if (!s.started || s.done) {
        return;
    }

    switch (s.phase) {
        case 0: /* 等开机 */
            s.boot_wait++;
            if (probe_boot_ready()) {
                probe_log("boot ready at %d ticks (%u ms), page=%d", s.boot_wait,
                          (unsigned)s.boot_wait * PROBE_TICK_MS,
                          (int)lvgl_page_current_id());
                s.phase = 1;
            } else if (s.boot_wait >= PROBE_BOOT_MAX) {
                probe_log("boot timeout");
                s.phase = 1;
            }
            return;

        case 1: /* 稳定若干拍再进菜单 */
            if (s.waited++ < 60) {
                return;
            }
            {
                int rc = lv_pm_open_page_msg((lv_pm_id)BICYCLE_PM_ID_MENU, LV_PM_MSG_NONE);

                probe_log("open menu rc=%d tick=%u", rc, (unsigned)lv_tick_get());
            }
            s.waited = 0;
            s.phase = 2;
            return;

        case 2: /* 等菜单驻留 60 拍 */
            if (lv_pm_nav_busy()) {
                if (++s.nav_wait >= 500) {
                    lv_pm_nav_drain();
                    s.nav_wait = 0;
                }
                return;
            }
            if (s.waited++ < 60) {
                return;
            }
            {
                int rc = lv_pm_close_page_msg(LV_PM_MSG_NONE);

                s.t0 = lv_tick_get();
                probe_log("close menu rc=%d t0=%u page=%d", rc, (unsigned)s.t0,
                          (int)lvgl_page_current_id());
            }
            s.waited = 0;
            s.phase = 3;
            sim_display_flush_reset();
            return;

