        return;
    }
    if (strlen(dir) >= sizeof(s.dir)) {
        fprintf(stderr, "[cta] dir too long\n");
        return;
    }
    strcpy(s.dir, dir);
    s.shots = (getenv("SIM_CTA_PROBE_SHOTS") != NULL);
    s.started = true;
    if (!probe_mkdir_p(s.dir)) {
        fprintf(stderr, "[cta] cannot create %s\n", s.dir);
        s.done = true;
        return;
    }
    probe_log("start dir=%s shots=%d", s.dir, (int)s.shots);
    s.tmr = lv_timer_create(probe_tick_cb, PROBE_TICK_MS, NULL);
    if (!s.tmr) {
        fprintf(stderr, "[cta] cannot create timer\n");
        s.done = true;
    }
}

bool sim_ui_cta_probe_done(void)
{
    return s.enabled && s.done;
}
