#include <string.h>
#include <sys/stat.h>
#include <sys/types.h>

#include "sim.h"
#include "sim_config.h"

#include "bicycle_page_ids.h"
#include "lvgl_page.h"
#include "lv_pm_core.h"
#include "live_map/map_page.h"

#define PROBE_TICK_MS   10u
#define PROBE_BOOT_MAX  2000

static struct {
    bool enabled;
    bool started;
    bool done;
    char dir[480];
    int phase;
    int waited;
    int boot_wait;
    int nav_wait;
    int n;
    int after;
    uint32_t t0;
    lv_timer_t *tmr;
} s;

static void probe_log(const char *fmt, ...)
{
    va_list ap;

    fputs("[fade] ", stdout);
    va_start(ap, fmt);
    vprintf(fmt, ap);
    va_end(ap);
    fputc('\n', stdout);
    fflush(stdout);
}

static bool probe_mkdir_p(const char *dir)
{
    char tmp[sizeof(s.dir)];
    size_t len = strlen(dir);

    if (len == 0 || len >= sizeof(tmp)) {
        return false;
    }
    memcpy(tmp, dir, len + 1);
    for (char *p = tmp + 1; *p; p++) {
        if (*p != '/') {
            continue;
        }
        *p = '\0';
        if (mkdir(tmp, 0777) != 0 && errno != EEXIST) {
            return false;
        }
        *p = '/';
    }
    if (mkdir(tmp, 0777) != 0 && errno != EEXIST) {
        return false;
    }
    return true;
}

/** 强制刷新后把整帧影子缓冲存成 PNG（headless 下影子就是整帧）。 */
static void probe_shot_name(const char *name)
{
    char path[sizeof(s.dir) + 96];
    const uint16_t *fb;
    int w = 0;
    int h = 0;

    lv_obj_invalidate(lv_screen_active());
    lv_refr_now(NULL);
    fb = sim_display_shadow(&w, &h);
    if (snprintf(path, sizeof(path), "%s/%s.png", s.dir, name) >= (int)sizeof(path)) {
        return;
    }
    if (!sim_png_write(path, fb, w, h)) {
        fprintf(stderr, "[fade] shot FAILED %s\n", path);
    }
}

static bool probe_boot_ready(void)
{
    bicycle_pm_id_t id = lvgl_page_current_id();

    if (lv_pm_nav_busy()) {
        return false;
    }
    if (id == BICYCLE_PM_ID_STARTUP) {
        return false;
    }
    return lvgl_page_map() != NULL;
}

static void probe_finish(void)
{
    s.done = true;
    if (s.tmr) {
        lv_timer_delete(s.tmr);
        s.tmr = NULL;
    }
    probe_log("done (%d samples)", s.n);
}

static void probe_tick_cb(lv_timer_t *tmr)
{
    (void)tmr;
    if (!s.started || s.done) {
        return;
    }

    switch (s.phase) {
        case 0: /* 等开机 */
            s.boot_wait++;
            if (probe_boot_ready()) {
                probe_log("boot ready at %d ticks (%u ms), page=%d", s.boot_wait,
                          (unsigned)s.boot_wait * PROBE_TICK_MS,
                          (int)lvgl_page_current_id());
                s.phase = 1;
            } else if (s.boot_wait >= PROBE_BOOT_MAX) {
                probe_log("boot timeout");
                s.phase = 1;
            }
            return;

        case 1: /* 稳定若干拍后存改前稳态图，再进菜单 */
            if (s.waited++ < 60) {
                return;
            }
            probe_shot_name("map_steady_before");
            {
                int rc = lv_pm_open_page_msg((lv_pm_id)BICYCLE_PM_ID_MENU, LV_PM_MSG_NONE);

                probe_log("open menu rc=%d tick=%u", rc, (unsigned)lv_tick_get());
            }
            s.waited = 0;
            s.phase = 2;
            return;

        case 2: /* 等菜单驻留 60 拍 */
            if (lv_pm_nav_busy()) {
                if (++s.nav_wait >= 500) {
                    lv_pm_nav_drain();
                    s.nav_wait = 0;
                }
                return;
            }
            if (s.waited++ < 60) {
                return;
            }
            probe_shot_name("menu_steady");
            {
                int rc = lv_pm_close_page_msg(LV_PM_MSG_NONE);

                s.t0 = lv_tick_get();
                probe_log("close menu rc=%d t0=%u page=%d", rc, (unsigned)s.t0,
                          (int)lvgl_page_current_id());
            }
            s.waited = 0;
            s.phase = 3;
            return;

        case 3: { /* 关菜单之后逐拍采样 */
            map_page_t *mp = lvgl_page_map();
            lv_obj_t *root = mp ? map_page_root(mp) : NULL;
            int opa = -1;
            char name[32];
            uint32_t t = lv_tick_elaps(s.t0);

            if (root != NULL) {
                opa = (int)lv_obj_get_style_opa(root, LV_PART_MAIN);
            }
            probe_log("t=%ums page_opa=%d", (unsigned)t, opa);
            snprintf(name, sizeof(name), "ret_%03d", s.n);
            probe_shot_name(name);
            if (++s.n >= s.after) {
                probe_shot_name("map_steady_after");
                probe_finish();
            }
            return;
        }

        default:
            probe_finish();
            return;
    }
}

void sim_ui_fade_probe_start(void)
{
    const char *dir = getenv("SIM_FADE_PROBE_DIR");
    const char *ticks = getenv("SIM_FADE_PROBE_TICKS");

    s.enabled = (dir != NULL && dir[0] != '\0');
    if (!s.enabled || s.started) {
        return;
    }
    if (strlen(dir) >= sizeof(s.dir)) {
        fprintf(stderr, "[fade] dir too long\n");
        return;
    }
    strcpy(s.dir, dir);
    s.after = (ticks != NULL && atoi(ticks) > 0) ? atoi(ticks) : 45;
    s.started = true;
    if (!probe_mkdir_p(s.dir)) {
        fprintf(stderr, "[fade] cannot create %s\n", s.dir);
        s.done = true;
        return;
    }
    probe_log("start dir=%s ticks=%d", s.dir, s.after);
    s.tmr = lv_timer_create(probe_tick_cb, PROBE_TICK_MS, NULL);
    if (!s.tmr) {
        fprintf(stderr, "[fade] cannot create timer\n");
        s.done = true;
    }
}

bool sim_ui_fade_probe_done(void)
{
    return s.enabled && s.done;
}
